// Do not edit this file. The hiring task is in contracts/VeriFiLoan.sol.
const { expect } = require("chai");
const { ethers } = require("hardhat");

describe("VeriFiLoan", function () {
  async function deployFixture() {
    const [owner, platform, borrower, stranger] = await ethers.getSigners();
    const VeriFiLoan = await ethers.getContractFactory("VeriFiLoan");
    const loan = await VeriFiLoan.deploy(platform.address);
    await loan.waitForDeployment();
    return { loan, owner, platform, borrower, stranger };
  }

  async function disburse(loan, platform, borrower, amountCents) {
    const offChainId = ethers.id("loan-pay");
    await loan
      .connect(platform)
      .createLoan(offChainId, borrower.address, amountCents, 1299, 12, 900);
    await loan.connect(platform).approveLoan(1);
    await loan.connect(platform).disburseLoan(1);
  }

  it("createLoan registers a pending loan", async function () {
    const { loan, platform, borrower } = await deployFixture();
    const offChainId = ethers.id("loan-uuid-1");

    await expect(
      loan
        .connect(platform)
        .createLoan(offChainId, borrower.address, 100000, 1299, 12, 8900)
    )
      .to.emit(loan, "LoanCreated")
      .withArgs(1, offChainId, borrower.address, 100000, 1299, 12);

    const stored = await loan.getLoan(1);
    expect(stored.borrower).to.equal(borrower.address);
    expect(stored.status).to.equal(0); // Pending
    expect(stored.amountCents).to.equal(100000);
    expect(stored.interestRateBps).to.equal(1299);
    expect(stored.termMonths).to.equal(12);
  });

  it("approve and disburse transitions status", async function () {
    const { loan, platform, borrower } = await deployFixture();
    await loan
      .connect(platform)
      .createLoan(ethers.id("loan-uuid-2"), borrower.address, 50000, 1299, 6, 8500);
    await loan.connect(platform).approveLoan(1);
    await loan.connect(platform).disburseLoan(1);

    const stored = await loan.getLoan(1);
    expect(stored.status).to.equal(2); // Disbursed
  });

  it("remainingOf returns outstanding balance", async function () {
    const { loan, platform, borrower } = await deployFixture();
    await disburse(loan, platform, borrower, 10_000);
    expect(await loan.remainingOf(1)).to.equal(10_000);
  });

  it("recordPayment by borrower reduces remaining", async function () {
    const { loan, platform, borrower } = await deployFixture();
    await disburse(loan, platform, borrower, 10_000);

    await loan.connect(borrower).recordPayment(1, 4_000);

    expect(await loan.paymentCount()).to.equal(1);
    const payment = await loan.payments(0);
    expect(payment.loanId).to.equal(1);
    expect(payment.payer).to.equal(borrower.address);
    expect(payment.amountCents).to.equal(4_000);
    expect(payment.remainingCents).to.equal(6_000);
    expect(await loan.remainingOf(1)).to.equal(6_000);

    const stored = await loan.getLoan(1);
    expect(stored.status).to.equal(2); // still Disbursed
  });

  it("recordPayment by platform is allowed", async function () {
    const { loan, platform, borrower } = await deployFixture();
    await disburse(loan, platform, borrower, 10_000);

    await loan.connect(platform).recordPayment(1, 1_000);
    expect(await loan.remainingOf(1)).to.equal(9_000);
  });

  it("recordPayment final marks repaid", async function () {
    const { loan, platform, borrower } = await deployFixture();
    await disburse(loan, platform, borrower, 10_000);

    await loan.connect(borrower).recordPayment(1, 10_000);

    expect(await loan.paymentCount()).to.equal(1);
    const payment = await loan.payments(0);
    expect(payment.amountCents).to.equal(10_000);
    expect(payment.remainingCents).to.equal(0);

    const stored = await loan.getLoan(1);
    expect(stored.status).to.equal(3); // Repaid
  });

  it("recordPayment rejects stranger", async function () {
    const { loan, platform, borrower, stranger } = await deployFixture();
    await disburse(loan, platform, borrower, 10_000);

    await expect(loan.connect(stranger).recordPayment(1, 100)).to.be.revertedWithCustomError(
      loan,
      "Unauthorized"
    );
    expect(await loan.paymentCount()).to.equal(0);
  });

  it("recordPayment rejects zero and overpayment", async function () {
    const { loan, platform, borrower } = await deployFixture();
    await disburse(loan, platform, borrower, 10_000);

    await expect(loan.connect(borrower).recordPayment(1, 0)).to.be.revertedWithCustomError(
      loan,
      "InvalidAmount"
    );
    await expect(loan.connect(borrower).recordPayment(1, 10_001)).to.be.revertedWithCustomError(
      loan,
      "InvalidAmount"
    );
    expect(await loan.paymentCount()).to.equal(0);
  });

  it("recordPayment rejects before disbursal", async function () {
    const { loan, platform, borrower } = await deployFixture();
    await loan
      .connect(platform)
      .createLoan(ethers.id("loan-not-disbursed"), borrower.address, 5_000, 1299, 6, 900);

    await expect(loan.connect(borrower).recordPayment(1, 100)).to.be.revertedWithCustomError(
      loan,
      "InvalidStatusTransition"
    );
  });
});
